#!/usr/bin/env bash
# run-oracle.sh — Runs the designs of oracle/designs/index.json natively
# (gfortran binary) and stores the verified outputs in oracle/reference/.
#
# Execution contract (source line 776):
#   open(unit=22,file='leparagliding.txt')  ->  the design MUST be named
#   leparagliding.txt in the cwd; the airfoils named in section 2 are read
#   from the cwd; outputs (DXF, lines.txt, logs) are written to the cwd.
#   oracle/designs/<id>/ holds exactly these inputs (scripts/build-designs.sh).
#
# Compiled source: build/fortran/leparagliding.f, regenerated by
# scripts/make-patched.sh. It is the SAME file as the WASM build: the oracle
# compares two compilers on identical source. The binary is always rebuilt.
#
# The program also writes to ../stl and ../xflr5. Each design runs twice (a
# and b), each run in its own tree build/oracle-runs/<design>-<a|b>/{run,stl,
# xflr5}; if both are bit-identical (determinism), run/ and the stl/ and
# xflr5/ outputs are copied to oracle/reference/<design>/ (stl/ and xflr5/ as
# subdirectories) with a sha256 manifest of every file. The large outputs
# (DXF, STL, SCAD) are then removed from the reference: only their sha256 is
# versioned, the files stay in build/oracle-runs/<design>-a/.
#
# When the official archive ships its own outputs
# (fortran/original/designs/<id>/official-outputs.sha256), the reference is
# also compared with them; official-outputs.known-diffs.tsv lists the expected
# differences and why (file<TAB>reason).
#
# Usage: docker compose run --rm oracle scripts/run-oracle.sh
set -uo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$ROOT/build/fortran/leparagliding.f"
BIN="$ROOT/build/oracle-native/a.out"
source "$ROOT/scripts/oracle-lib.sh"
mapfile -t DESIGNS < <(design_ids)

"$ROOT/scripts/make-patched.sh" || exit 1
echo "native build: gfortran $(gfortran -dumpfullversion) $SRC"
mkdir -p "$ROOT/build/oracle-native"
gfortran -o "$BIN" "$SRC" 2> "$ROOT/build/oracle-native/gfortran-compile.log" || exit 1

FAIL=0
for D in "${DESIGNS[@]}"; do
  echo "=== $D ==="
  OK=1
  for K in a b; do
    T="$ROOT/build/oracle-runs/$D-$K"
    R="$T/run"
    rm -rf "$T"; mkdir -p "$R" "$T/stl" "$T/xflr5"   # ../stl, ../xflr5 of the program
    cp "$ROOT/oracle/designs/$D/"* "$R/"
    ( cd "$R" && "$BIN" leparagliding.txt > stdout.log 2> stderr.log )
    echo "[$D/$K] exit=$?"
    for f in lines.txt run-log.txt lep-3d.dxf leparagliding.dxf; do
      [ -s "$R/$f" ] || { echo "[$D/$K] MISSING OR EMPTY OUTPUT: $f"; OK=0; }
    done
  done

  if [ "$OK" -ne 1 ]; then FAIL=1; continue; fi

  HA=$(hash_tree "$ROOT/build/oracle-runs/$D-a")
  HB=$(hash_tree "$ROOT/build/oracle-runs/$D-b")
  if [ "$HA" = "$HB" ]; then
    echo "[$D] deterministic: run-a == run-b"
    REF="$ROOT/oracle/reference/$D"
    rm -rf "$REF"; mkdir -p "$REF"
    cp -R "$ROOT/build/oracle-runs/$D-a/run/." "$REF/"
    for S in stl xflr5; do
      [ -n "$(ls -A "$ROOT/build/oracle-runs/$D-a/$S")" ] && cp -R "$ROOT/build/oracle-runs/$D-a/$S" "$REF/"
    done
    hash_tree "$REF" > "$REF/MANIFEST.sha256"
    echo "[$D] reference -> oracle/reference/$D"
    OFF="$ROOT/fortran/original/designs/$D/official-outputs.sha256"
    if [ -f "$OFF" ]; then
      declare -A KNOWN=()   # file -> reason
      KD=$(known_diffs "${OFF%.sha256}.known-diffs.tsv" 2) || FAIL=1
      while IFS=$'\t' read -r F REASON; do
        [ -n "$F" ] && KNOWN["$F"]="$REASON"
      done <<< "$KD"
      while IFS= read -r LINE; do
        SUM="${LINE%%  *}"
        NAME="${LINE#*  }"
        REASON="${KNOWN["$NAME"]-}"
        if [ "$(sha256sum < "$REF/$NAME" | cut -d' ' -f1)" = "$SUM" ]; then
          echo "[$D] $NAME identical to the official output"
          [ -n "$REASON" ] && echo "[$D] $NAME: remove it from official-outputs.known-diffs.tsv"
        elif [ -n "$REASON" ]; then
          echo "[$D] $NAME differs from the official output (known: $REASON)"
        else
          echo "[$D] $NAME DIFFERS FROM THE OFFICIAL OUTPUT"; FAIL=1
        fi
      done < "$OFF"
      unset KNOWN
    fi
    find "$REF" \( -name '*.dxf' -o -name '*.stl' -o -name '*.scad' \) -delete
    find "$REF" -mindepth 1 -type d -empty -delete
  else
    echo "[$D] NOT DETERMINISTIC, run-a / run-b diff:"
    diff <(echo "$HA") <(echo "$HB") | head -20
    FAIL=1
  fi
done

[ "$FAIL" -eq 0 ] && echo "NATIVE ORACLE: OK" || echo "NATIVE ORACLE: FAILED"
exit "$FAIL"
